def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Key functions for different periodic patterns
    # key_funcs assumes args (r, c, H)
    key_funcs = [
        lambda r, c, H: c % H,   # Vertical periodicity (cols are constant)
        lambda r, c, H: r % H,   # Horizontal periodicity (rows are constant)
        lambda r, c, H: (c - r) % H, # Diagonal periodicity (diagonals are constant)
        lambda r, c, H: (r + c) % H  # Anti-diagonal periodicity
    ]

    limit_H = max(rows, cols) + 1

    # Iterate through all combinations of pattern type, period, and noise
    for func in key_funcs:
        for H in range(1, limit_H + 1):
            for n in range(10):
                map_mask = {}
                inconsistent = False

                # Check consistency of grid values against the pattern
                for r in range(rows):
                    for c in range(cols):
                        val = grid[r][c]
                        # Skip the noise value n
                        if val == n:
                            continue

                        key = func(r, c, H)
                        if key not in map_mask:
                            map_mask[key] = val
                        elif map_mask[key] != val:
                            inconsistent = True
                            break
                    if inconsistent:
                        break

                if not inconsistent:
                    # Found a consistent pattern that explains the data
                    res = [[0] * cols for _ in range(rows)]

                    # Reconstruct the grid using the derived pattern
                    for r in range(rows):
                        for c in range(cols):
                            key = func(r, c, H)
                            # If the key maps to a value, use it
                            if key in map_mask:
                                res[r][c] = map_mask[key]
                            else:
                                # If no valid value was found for this key (all were noise),
                                # fall back to n or 0. Since 0 is often noise/background.
                                res[r][c] = n

                    return res

    # Fallback
    return grid
